"""Fixed legal text appended by code, never generated by the LLM (ADR-06, docs/spec.md 19.C).

DRAFT: both clauses are to be validated by a consumer-law professional before any real use (open
question D-14). The guarantee clause is a proposed draft; it follows Directive (EU) 2019/771,
art. 13 and 14: repair or replacement first, free of charge and within a reasonable time; a price
reduction or termination of the contract where applicable, never for a minor defect.

When a clause is required (`required_clause`):
- withdrawal: on the withdrawal path, when the decision has restrictive levers (Q3, Q4);
- guarantee: always on the guarantee path.
A missing or altered clause in a final message is a bug in the code, never in the model:
`assert_clause` raises `LegalClauseError` (spec 8.7, blocking error).
"""

from __future__ import annotations

from typing import Literal

from llm.text import Lang
from policy.legal_guard import is_restrictive
from policy.types import Decision, Path, ReturnTerms

ClauseKind = Literal["withdrawal", "guarantee"]

CLAUSES: dict[ClauseKind, dict[Lang, str]] = {
    "withdrawal": {
        "it": (
            "Ti ricordiamo che puoi sempre esercitare il diritto di recesso entro 14 giorni "
            "dalla consegna, senza indicarne il motivo. Ti rimborseremo entro 14 giorni dalla "
            "tua comunicazione, al ricevimento dei prodotti o della prova della loro spedizione."
        ),
        "en": (
            "You can always withdraw from your purchase within 14 days of delivery without giving "
            "any reason. We will refund you within 14 days of your notice, once we receive the "
            "items or proof that you have sent them back."
        ),
    },
    # Proposed draft (LLM-11), pending D-14.
    "guarantee": {
        "it": (
            "Il prodotto è coperto dalla garanzia legale di conformità. Puoi chiedere prima di "
            "tutto la riparazione o la sostituzione, senza spese ed entro un periodo ragionevole. "
            "Nei casi previsti dalla legge, per esempio se la riparazione o la sostituzione non "
            "sono possibili o non eliminano il difetto, puoi chiedere una riduzione del prezzo "
            "oppure, se il difetto non è di lieve entità, la risoluzione del contratto con la "
            "restituzione del prezzo."
        ),
        "en": (
            "The item is covered by the legal guarantee of conformity. You can first ask for a "
            "repair or a replacement, free of charge and within a reasonable time. Where the law "
            "provides for it, for example if a repair or a replacement is not possible or does "
            "not remove the defect, you can ask for a price reduction or, unless the defect is "
            "minor, end the contract and get the price back."
        ),
    },
}


class LegalClauseError(RuntimeError):
    """A final message without the required clause, or with an altered one: a code bug."""


def clause(kind: ClauseKind, lang: Lang) -> str:
    return CLAUSES[kind][lang]


def required_clause(decision: Decision, base: ReturnTerms) -> ClauseKind | None:
    """The clause a customer message for this decision must end with, or None."""
    if decision.path is Path.GUARANTEE:
        return "guarantee"
    if is_restrictive(decision.levers, base):
        return "withdrawal"
    return None


def append_clause(text: str, kind: ClauseKind | None, lang: Lang) -> str:
    if kind is None:
        return text
    return f"{text.rstrip()}\n\n{clause(kind, lang)}"


def assert_clause(final_text: str, kind: ClauseKind | None, lang: Lang) -> None:
    """Raise LegalClauseError unless the text ends with exactly the required clause, once, and
    holds no other clause."""
    for other, texts in CLAUSES.items():
        if other != kind and texts[lang] in final_text:
            raise LegalClauseError(f"Unexpected {other} clause in a {lang} message")
    if kind is None:
        return
    expected = clause(kind, lang)
    if final_text.count(expected) != 1 or not final_text.endswith(f"\n\n{expected}"):
        raise LegalClauseError(f"The {kind} clause ({lang}) is missing or altered")
